/* r4b1t motion compatibility shim + dual-shell loader */
(function(){
  function list(targets){
    if(!targets)return[];
    if(typeof targets==='string')return Array.from(document.querySelectorAll(targets));
    if(targets instanceof Element)return[targets];
    return Array.from(targets.length!==undefined?targets:[]);
  }
  function anime(options){
    options=options||{};
    var timer=setTimeout(function(){if(typeof options.complete==='function')options.complete();},Math.max(0,Number(options.duration)||0));
    return{pause:function(){clearTimeout(timer);}};
  }
  anime.remove=function(){};
  anime.set=function(targets,props){
    list(targets).forEach(function(el){
      if(!el||!el.style)return;
      if(props&&props.translateX!==undefined)el.style.transform='translateX('+props.translateX+'px)';
      if(props&&props.opacity!==undefined)el.style.opacity=String(props.opacity);
    });
  };
  window.anime=anime;
  document.write('<link rel="stylesheet" href="dual-shell.css"><script defer src="dual-shell.js"><\/script>');
})();
